  resumo: DashboardResumo;
  cotacoes_atuais: Cotacoes;
  data_atualizacao: string;
}

@Component({
  selector: 'app-dashboard',
  standalone: true,
  imports: [CommonModule, RouterLink],
  templateUrl: './dashboard.component.html',
  styleUrls: ['./dashboard.component.scss']
})
export class DashboardComponent implements OnInit {
  isLoading = true;
  hasError = false;
  errorMessage = '';
  isExporting = false;

  resumo: DashboardResumo | null = null;
  cotacoes: Cotacoes | null = null;
  dataAtualizacao: string | null = null;

  // Valores convertidos
  saldoEmUSD = 0;
  saldoEmEUR = 0;
  receitasEmUSD = 0;
  despesasEmUSD = 0;

  constructor(
    private dashboardService: DashboardService,
    private exportService: ExportService
  ) {}

  ngOnInit(): void {
    this.carregarDados();
  }

  private carregarDados(): void {
    this.isLoading = true;
    this.hasError = false;

    this.dashboardService.obterResumo().subscribe({
      next: (response: any) => {
        if (response.success && response.data) {
          this.resumo = response.data;
          this.cotacoes = response.data.cotacoes || {};
          this.dataAtualizacao = new Date().toLocaleString('pt-BR');

          this.calcularConversoes();
        }
        this.isLoading = false;
      },
      error: (error: any) => {
        console.error('Erro ao carregar dashboard:', error);
        this.hasError = true;
        this.errorMessage = 'Erro ao carregar dados do dashboard. Tente novamente.';
        this.isLoading = false;
      }
    });
  }

  private calcularConversoes(): void {
    if (!this.resumo || !this.cotacoes) return;

    const cotacaoUSD = this.cotacoes.USD_BRL?.cotacao || 0;
    const cotacaoEUR = this.cotacoes.EUR_BRL?.cotacao || 0;

    if (cotacaoUSD > 0) {
      this.saldoEmUSD = this.resumo.saldo_atual / cotacaoUSD;
      this.receitasEmUSD = this.resumo.receitas / cotacaoUSD;
      this.despesasEmUSD = this.resumo.despesas / cotacaoUSD;
    }

    if (cotacaoEUR > 0) {
      this.saldoEmEUR = this.resumo.saldo_atual / cotacaoEUR;
    }
  }

  recarregar(): void {
    this.carregarDados();
  }

  /**
   * Inicia o download do relatório CSV
   */
  exportarCsv(): void {
    this.isExporting = true;
    this.hasError = false;

    try {
      this.exportService.exportarCsv('relatorio_financeiro.csv');
      this.isExporting = false;
    } catch (error: any) {
      console.error('Erro ao exportar:', error);
      this.hasError = true;
      this.errorMessage = error.message || 'Erro ao exportar o relatório. Tente novamente.';
      this.isExporting = false;
    }
  }

  formatarMoeda(valor: number, moeda: string = 'BRL'): string {
    const locale = 'pt-BR';
    return new Intl.NumberFormat(locale, {
      style: 'currency',
      currency: moeda
    }).format(valor);
  }
}
<div class="dashboard-container">
  <!-- Header -->
  <div class="dashboard-header">
    <h1>Dashboard Financeiro</h1>
    <p class="subtitle">Resumo da sua situação financeira</p>
  </div>

  <!-- Loading State -->
  <div *ngIf="isLoading" class="loading-state">
    <div class="spinner"></div>
    <p>Carregando dados...</p>
  </div>

  <!-- Error State -->
  <div *ngIf="hasError && !isLoading" class="error-state">
    <div class="error-icon">⚠️</div>
    <h3>Erro ao carregar</h3>
    <p>{{ errorMessage }}</p>
    <button class="btn-retry" (click)="recarregar()">
      🔄 Tentar novamente
    </button>
  </div>

  <!-- Content -->
  <div *ngIf="!isLoading && !hasError && resumo" class="dashboard-content">
    <!-- Main Cards Grid -->
    <div class="cards-grid">
      <!-- Card Principal: Saldo Atual -->
      <div class="card card-saldo">
        <div class="card-header">
          <h2>Saldo Atual</h2>
          <span class="update-time">Atualizado em {{ dataAtualizacao | date:'HH:mm:ss' }}</span>
        </div>
        <div class="card-body">
          <div class="saldo-principal">
            <span class="currency-symbol">R$</span>
            <span class="saldo-value" [class.positive]="resumo.saldo_atual >= 0" [class.negative]="resumo.saldo_atual < 0">
              {{ formatarMoeda(resumo.saldo_atual) }}
            </span>
          </div>
          
          <!-- Conversões -->
          <div class="conversoes" *ngIf="cotacoes">
            <div class="conversao">
              <span class="label">Em USD:</span>
              <span class="valor">{{ formatarMoeda(saldoEmUSD, 'USD') }}</span>
            </div>
            <div class="conversao">
              <span class="label">Em EUR:</span>
              <span class="valor">{{ formatarMoeda(saldoEmEUR, 'EUR') }}</span>
            </div>
          </div>

          <!-- Status Badge -->
          <div class="status-badge" [class.positivo]="resumo.saldo_atual >= 0" [class.negativo]="resumo.saldo_atual < 0">
            <span *ngIf="resumo.saldo_atual >= 0">✓ Você está com saldo positivo</span>
            <span *ngIf="resumo.saldo_atual < 0">⚠️ Você está devendo</span>
          </div>
        </div>
      </div>

      <!-- Card Secundário: Receitas -->
      <div class="card card-receitas">
        <div class="card-header">
          <h3>Receitas</h3>
          <span class="card-icon">📈</span>
        </div>
        <div class="card-body">
          <div class="valor-grande">
            {{ formatarMoeda(resumo.receitas) }}
          </div>
          <div class="conversao-simples">
            USD: {{ formatarMoeda(receitasEmUSD, 'USD') }}
          </div>
          <p class="card-footer-text">Total de entradas</p>
        </div>
      </div>

      <!-- Card Secundário: Despesas -->
      <div class="card card-despesas">
        <div class="card-header">
          <h3>Despesas</h3>
          <span class="card-icon">📉</span>
        </div>
        <div class="card-body">
          <div class="valor-grande negativo">
            {{ formatarMoeda(resumo.despesas) }}
          </div>
          <div class="conversao-simples">
            USD: {{ formatarMoeda(despesasEmUSD, 'USD') }}
          </div>
          <p class="card-footer-text">Total de saídas</p>
        </div>
      </div>

      <!-- Card Informativo: Estatísticas -->
      <div class="card card-stats">
        <div class="card-header">
          <h3>Estatísticas</h3>
          <span class="card-icon">📊</span>
        </div>
        <div class="card-body">
          <div class="stat-item">
            <span class="stat-label">Total de Transações:</span>
            <span class="stat-value">{{ resumo.total_transacoes }}</span>
          </div>
          <div class="stat-item">
            <span class="stat-label">Proporção:</span>
            <span class="stat-value">
              {{ ((resumo.receitas - resumo.despesas) / resumo.receitas * 100 | number:'1.0-0') }}%
            </span>
          </div>
          <button class="btn-details" routerLink="/transacoes">
            Ver todas as transações →
          </button>
        </div>
      </div>
    </div>

    <!-- Cotações Card -->
    <div *ngIf="cotacoes" class="cotacoes-card">
      <div class="cotacoes-header">
        <h3>🌍 Cotações Atuais</h3>
        <span class="last-update">Última atualização: {{ dataAtualizacao | date:'dd/MM/yyyy HH:mm' }}</span>
      </div>

      <div class="cotacoes-grid">
        <!-- USD -->
        <div *ngIf="cotacoes.USD_BRL" class="cotacao-item">
          <div class="cotacao-header">
            <span class="moeda">USD/BRL</span>
            <span class="flag">🇺🇸</span>
          </div>
          <div class="cotacao-valor">
            {{ cotacoes.USD_BRL.cotacao | number:'1.2-2' }}
          </div>
          <div class="cotacao-info">
            <span class="label">Mínima:</span>
            <span class="valor">{{ cotacoes.USD_BRL.baixa | number:'1.2-2' }}</span>
          </div>
          <div class="cotacao-info">
            <span class="label">Máxima:</span>
            <span class="valor">{{ cotacoes.USD_BRL.alta | number:'1.2-2' }}</span>
          </div>
        </div>

        <!-- EUR -->
        <div *ngIf="cotacoes.EUR_BRL" class="cotacao-item">
          <div class="cotacao-header">
            <span class="moeda">EUR/BRL</span>
            <span class="flag">🇪🇺</span>
          </div>
          <div class="cotacao-valor">
            {{ cotacoes.EUR_BRL.cotacao | number:'1.2-2' }}
          </div>
          <div class="cotacao-info">
            <span class="label">Mínima:</span>
            <span class="valor">{{ cotacoes.EUR_BRL.baixa | number:'1.2-2' }}</span>
          </div>
          <div class="cotacao-info">
            <span class="label">Máxima:</span>
            <span class="valor">{{ cotacoes.EUR_BRL.alta | number:'1.2-2' }}</span>
          </div>
        </div>
      </div>
    </div>

    <!-- Action Buttons -->
    <div class="action-buttons">
      <button class="btn btn-success" (click)="exportarCsv()" [disabled]="isExporting" title="Baixar relatório em CSV">
        <span *ngIf="!isExporting">📊 Exportar Relatório CSV</span>
        <span *ngIf="isExporting">⏳ Exportando...</span>
      </button>
      <button class="btn btn-primary" routerLink="/transacoes">
        💸 Ir para Transações
      </button>
      <button class="btn btn-secondary" routerLink="/categorias">
        🏷️ Gerenciar Categorias
      </button>
      <button class="btn btn-tertiary" (click)="recarregar()">
        🔄 Atualizar Dados
      </button>
    </div>
  </div>
</div>
